<script>
  import { onMount } from 'svelte'
  import { manageAdminSubscription, fetchAdminUserDetail, fetchAdminUsers } from '../../lib/api.js'
  export let onRefresh
  export let canManage = true
  let users=[];let total=0;let cursor=0;let nextCursor=null;let query='';let filter='all';let sort='new';let usage='all';let cohort='all';let loading=true
  let selected=null;let days=30;let busy=false;let notice='';let noticeKind='info';let loadError='';let detailError='';let detail=null;let detailLoading=false;let searchTimer;let presenceSource='';let listRequest=0;let detailRequest=0
  const rub=v=>`${new Intl.NumberFormat('ru-RU').format(Number(v||0))} ₽`
  const date=v=>v?new Date(String(v).includes('T')?v:String(v).replace(' ','T')+'Z').toLocaleString('ru-RU',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'—'
  const bytes=v=>Number(v||0)>0?`${(Number(v)/1024**3).toFixed(1)} ГБ`:'0 ГБ'
  function daysLeft(value){return value?Math.max(0,Math.ceil((new Date(String(value).replace(' ','T')+'Z')-Date.now())/86400000)):0}
  async function load({append=false,preserveNotice=false}={}){const request=++listRequest;loading=true;loadError='';if(!preserveNotice)notice='';try{const result=await fetchAdminUsers({q:query.trim(),status:filter,sort,usage,cohort,cursor:append?nextCursor||0:0,limit:40});if(request!==listRequest)return;users=append?[...users,...(result.users||[])]:result.users||[];total=result.total||0;cursor=result.cursor||0;nextCursor=result.next_cursor;presenceSource=result.presence_source||''}catch(e){if(request===listRequest)loadError=`Не удалось загрузить пользователей: ${e.reason||e.message}`}finally{if(request===listRequest)loading=false}}
  function chooseFilter(value){filter=value;selected=null;detail=null;load()}
  function chooseSort(value){sort=value;load()}
  function chooseUsage(value){usage=value;load()}
  function chooseCohort(value){cohort=value;load()}
  function search(){clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),280)}
  async function refreshDetail(user){const request=++detailRequest;selected=user.telegram_id;detailLoading=true;detailError='';try{const result=await fetchAdminUserDetail(user.telegram_id);if(request===detailRequest&&selected===user.telegram_id)detail=result}catch(e){if(request===detailRequest)detailError=`Не удалось открыть карточку: ${e.reason||e.message}`}finally{if(request===detailRequest)detailLoading=false}}
  async function open(user){if(selected===user.telegram_id){detailRequest++;selected=null;detail=null;detailError='';return}detail=null;await refreshDetail(user)}
  async function act(user,action,payload={}){if(!canManage||busy)return;busy=true;notice='';try{const result=await manageAdminSubscription(user.telegram_id,{action,...payload});users=users.map(item=>item.telegram_id===user.telegram_id?{...item,expires_at:result.expires_at,active:result.active?1:0}:item);if(detail?.subscriptions?.length){detail={...detail,subscriptions:detail.subscriptions.map(sub=>sub.id===result.key_id?{...sub,...result.subscription}:sub),timeline:result.timeline_event?[result.timeline_event,...(detail.timeline||[])]:detail.timeline}}notice='Изменение сохранено и подтверждено панелью';noticeKind='success';Promise.resolve().then(()=>onRefresh?.())}catch(e){notice=`Ошибка: ${e.reason||e.message}`;noticeKind='error'}finally{busy=false}}
  onMount(load)
</script>

<section class="page">
  <p class="page-intro">Поиск по всей базе, история оплат и управление доступом без терминала.</p>
  <div class="command"><label><span>ПОИСК</span><input aria-label="Поиск пользователей" bind:value={query} on:input={search} placeholder="Имя, @username или Telegram ID" /></label><label><span>СОРТИРОВКА</span><select aria-label="Сортировка пользователей" bind:value={sort} on:change={()=>chooseSort(sort)}><option value="new">Сначала новые</option><option value="top">По оплатам</option><option value="main_usage">Топ по основному трафику</option><option value="lte_usage">Топ по LTE-трафику</option><option value="online">Сначала онлайн</option><option value="expiry">Скоро закончатся</option></select></label><label><span>ТРАФИК</span><select aria-label="Фильтр по использованию трафика" bind:value={usage} on:change={()=>chooseUsage(usage)}><option value="all">Любое использование</option><option value="main">Тратил основной</option><option value="lte">Тратил LTE</option></select></label><label><span>КОГОРТА</span><select aria-label="Фильтр по типу клиента" bind:value={cohort} on:change={()=>chooseCohort(cohort)}><option value="all">Все клиенты</option><option value="email_paid_trial">Пробник за 10 ₽</option></select></label><strong aria-live="polite">{total.toLocaleString('ru-RU')}<small>пользователей</small></strong></div>
  <nav aria-label="Фильтр пользователей">{#each [['all','Все'],['active','Активные'],['online','Онлайн'],['inactive','Неактивные']] as item}<button aria-current={filter===item[0]?'page':undefined} class:active={filter===item[0]} on:click={()=>chooseFilter(item[0])}>{item[1]}</button>{/each}</nav>
  {#if notice}<p class="notice" class:error={noticeKind==='error'} role={noticeKind==='error'?'alert':'status'}>{notice}</p>{/if}
  {#if loadError}<div class="state error" role="alert"><span>{loadError}</span><button on:click={()=>load()} disabled={loading}>Повторить</button></div>{/if}
  {#if loading && !users.length}<div class="empty" role="status">Собираем клиентскую базу…</div>{:else if !loadError&&!users.length}<div class="empty">{filter==='online'?'Remnawave не видит активных пользователей за последние 3 минуты.':'По этому запросу пользователей нет.'}</div>{/if}
  {#if users.length}<div class="list-head" aria-hidden="true"><span>Клиент</span><span>Оплаты</span><span>Подписка</span><span>Трафик</span><span>Статус</span></div>{/if}
  <div class="list">{#each users as user}<article class:opened={selected===user.telegram_id}>
    <button class="summary" aria-expanded={selected===user.telegram_id} aria-controls={`user-${user.telegram_id}`} on:click={()=>open(user)}><div class="identity"><b>{user.first_name||user.username||`ID ${user.telegram_id}`}</b><small>@{user.username||'без username'} · ID {user.telegram_id}</small>{#if Number(user.online_devices)>0}<em>{user.online_node||'Remnawave'}</em>{/if}</div><span class="cell"><small>Оплаты</small><b>{rub(user.paid_rub)}</b></span><span class="cell"><small>Подписка</small><b>{date(user.expires_at)}</b></span><span class="cell traffic"><small class="sr-only">Трафик</small><b><span>Основной</span>{bytes(user.main_used_bytes)}</b><b><span>LTE</span>{bytes(user.lte_used_bytes)}</b></span><span class:ok={user.active} class="status">{user.active?(Number(user.online_devices)>0?'Онлайн':'Активен'):'Неактивен'}</span></button>
    {#if selected===user.telegram_id}<div class="drawer" id={`user-${user.telegram_id}`}>
      {#if detailLoading}<p>Собираем подписки, платежи, устройства и журнал действий…</p>{:else if detail}
        <div class="facts"><span><small>СРОК</small><b>{daysLeft(detail.subscriptions?.[0]?.expires_at)} дней</b></span><span><small>ДЕЙСТВУЕТ ДО</small><b>{date(detail.subscriptions?.[0]?.expires_at)}</b></span><span><small>ОСНОВНОЙ ТРАФИК</small><b>{bytes((detail.subscriptions||[]).reduce((sum,item)=>sum+Number(item.traffic_used||0),0))}</b></span><span><small>LTE-ТРАФИК</small><b>{bytes(detail.user?.lte_used_bytes)}{#if Number(detail.user?.lte_quota_gb)>0} / {detail.user.lte_quota_gb} ГБ{/if}</b></span><span><small>БАЛАНС</small><b>{rub(detail.user?.balance_rub)}</b></span><span><small>УСТРОЙСТВА</small><b>{(detail.devices||[]).filter(d=>d.active).length}/{detail.user?.device_limit||2}</b></span></div>
        <div class="columns"><section><header><b>Подписки</b><span>{detail.subscriptions?.length||0}</span></header>{#each detail.subscriptions||[] as sub}<article><div><b>{sub.custom_name||sub.tariff_name||`Подписка #${sub.id}`}</b><small>{sub.active?'Активна':'Завершена'} · до {date(sub.expires_at)} · {bytes(sub.traffic_used)}</small></div><em>{sub.online_devices||0} онлайн</em></article>{/each}</section>
        <section><header><b>Оплаты</b><span>{detail.payments?.length||0}</span></header>{#each detail.payments||[] as payment}<article><div><b>{Number(payment.amount_rub)>0?rub(payment.amount_rub):Number(payment.amount_usd)>0?`$${Number(payment.amount_usd).toFixed(2)}`:`${payment.amount_stars||0} Stars`}</b><small>{payment.tariff_name||payment.payment_type} · {date(payment.paid_at)}</small></div><em class:paid={['paid','succeeded'].includes(payment.status)}>{payment.status}</em></article>{/each}</section></div>
        <section class="timeline"><header><b>История клиента</b><span>{detail.timeline?.length||0} событий</span></header>{#each detail.timeline||[] as event}<article><i class={event.kind}></i><div><b>{event.title}</b><small>{event.detail}</small></div><time>{date(event.at)}</time></article>{/each}{#if !detail.timeline?.length}<p>Событий пока нет.</p>{/if}</section>
      {:else if detailError}<div class="state error" role="alert"><span>{detailError}</span><button on:click={()=>refreshDetail(user)}>Повторить</button></div>{/if}
      <div class="actions"><label>Дней <input aria-label="Количество дней" type="number" min="1" max="1095" bind:value={days}/></label><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'adjust_days',{days:Number(days)})}>Добавить</button><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'adjust_days',{days:-Number(days)})}>Убрать</button><button disabled={busy||!canManage||days<1||days>1095} on:click={()=>act(user,'activate_days',{days:Number(days)})}>Активировать от сегодня</button><button disabled={busy||!canManage} on:click={()=>confirm('Обнулить использованный трафик обхода, сохранив лимит?')&&act(user,'reset_lte_traffic')}>Сбросить трафик обхода</button><button disabled={busy||!canManage} on:click={()=>confirm('Старая ссылка и ссылки устройств перестанут работать. Перевыпустить?')&&act(user,'regenerate_url')}>Перевыпустить ссылки</button><button disabled={busy||!canManage} class="danger" on:click={()=>confirm('Отключить подписку пользователя?')&&act(user,'disable')}>Отключить</button></div>
    </div>{/if}
  </article>{/each}</div>
  {#if filter==='online'&&presenceSource}<small class="presence">Источник присутствия: {presenceSource==='remnawave'?'Remnawave live':'локальный резерв'}</small>{/if}
  {#if nextCursor!==null}<button class="more" disabled={loading} on:click={()=>load({append:true})}>{loading?'Загружаем…':`Показать ещё · осталось ${Math.max(0,total-users.length)}`}</button>{/if}
</section>

<style>
.page{display:grid;gap:16px;min-width:0;width:100%;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;font-size:14px;color:#eaf0f8}
.page-intro{margin:0;color:#a6b4c8;font-size:14px;line-height:1.6}
.command{display:grid;grid-template-columns:minmax(240px,2fr) repeat(3,minmax(150px,1fr));gap:12px;align-items:end;padding:20px;background:#131c2b;border:1px solid #2b384b;border-radius:16px}
.command label{display:grid;gap:8px;min-width:0}.command label span{font-size:12px;font-weight:500;color:#a6b4c8}
.command input,.command select{box-sizing:border-box;width:100%;min-width:0;height:44px;padding:0 12px;border:1px solid #37465d;border-radius:9px;background:#0e1623;color:#eaf0f8;font:inherit}
.command select option{background:#131c2b}.command>strong{grid-column:1/-1;font-size:14px;color:#eaf0f8;font-weight:600}.command>strong small{margin-left:7px;font-size:14px;color:#a6b4c8;font-weight:400}
.page>nav{display:flex;gap:6px;flex-wrap:wrap}.page>nav button{min-height:42px;padding:0 18px;border:1px solid transparent;border-radius:9px;background:transparent;color:#a6b4c8;font:inherit;cursor:pointer}.page>nav button.active{color:#b8dfff;background:#203c59;border-color:#365d80}
.list-head,.summary{display:grid;grid-template-columns:minmax(180px,1.2fr) minmax(100px,.6fr) minmax(165px,1fr) minmax(170px,1fr) 100px;align-items:center;gap:20px}
.list-head{padding:0 20px;font-size:12px;color:#a6b4c8;font-weight:500}.list{border:1px solid #2b384b;border-radius:14px;overflow:hidden;background:#131c2b}
.list>article{border-bottom:1px solid #29364a}.list>article:last-child{border-bottom:0}.list>article.opened{background:#17253a}
.summary{box-sizing:border-box;width:100%;min-height:82px;padding:16px 20px;border:0;background:transparent;color:#eaf0f8;text-align:left;font:inherit;cursor:pointer}.summary:hover{background:#1b2a40}
.identity{display:grid;gap:5px;min-width:0}.identity b{font-size:15px;font-weight:600;overflow-wrap:anywhere}.identity small{font-size:12px;color:#a6b4c8;overflow-wrap:anywhere}.identity em{font-size:12px;color:#82e0b5;font-style:normal;overflow-wrap:anywhere}
.cell{display:grid;gap:5px;min-width:0}.cell>small{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.cell b{font-size:14px;font-weight:500;line-height:1.5;font-variant-numeric:tabular-nums}
.traffic b{display:flex;justify-content:space-between;gap:12px}.traffic b span{color:#a6b4c8;font-size:12px;font-weight:400}
.status{justify-self:start;white-space:nowrap;padding:6px 10px;border-radius:7px;background:#382331;color:#ffb4bf;font-size:12px;font-weight:500}.status.ok{background:#173c33;color:#82e0b5}
.drawer{padding:20px;border-top:1px solid #36475f}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin-bottom:20px;background:#101a29;border:1px solid #2b384b;border-radius:12px;overflow:hidden}.facts>span{padding:16px 18px;border-bottom:1px solid #29364a;min-width:0}.facts small,.facts b{display:block}.facts small{font-size:12px;color:#a6b4c8}.facts b{margin-top:8px;font-size:17px;font-weight:600;overflow-wrap:anywhere}
.columns{display:grid;grid-template-columns:1fr 1fr;gap:20px}.columns>section,.timeline{padding:18px;background:#101a29;border:1px solid #2b384b;border-radius:12px;min-width:0}.columns section>header,.timeline>header{display:flex;justify-content:space-between;gap:12px;margin-bottom:14px}.columns header b,.timeline header b{font-size:16px;font-weight:600}.columns header span,.timeline header span{font-size:13px;color:#a6b4c8}
.columns section>article{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-top:1px solid #29364a}.columns article div{display:grid;gap:6px;min-width:0}.columns article b{font-weight:500}.columns article small,.timeline small{font-size:13px;color:#a6b4c8;line-height:1.5;overflow-wrap:anywhere}.columns article em{font-size:12px;color:#a6b4c8;font-style:normal}.columns article em.paid{color:#82e0b5}
.timeline{margin-top:20px}.timeline article{display:grid;grid-template-columns:8px minmax(0,1fr) auto;gap:14px;align-items:center;padding:14px 0;border-top:1px solid #29364a}.timeline article>i{width:7px;height:7px;border-radius:50%;background:#7fcaff}.timeline article>i.payment{background:#82e0b5}.timeline article>i.admin{background:#f0c080}.timeline article div{display:grid;gap:5px}.timeline article b{font-size:14px;font-weight:500}.timeline time{font-size:12px;color:#a6b4c8}
.actions{display:flex;flex-wrap:wrap;gap:10px;padding-top:20px}.actions label,.actions button,.more,.state button{box-sizing:border-box;min-height:42px;padding:0 14px;border:1px solid #3b506b;border-radius:9px;background:#22354d;color:#dbedff;font:inherit;font-size:13px;cursor:pointer}.actions label{display:flex;align-items:center;gap:10px}.actions input{width:65px;min-height:32px;border:0;background:#101a29;color:#fff;font:inherit}.actions button.danger{margin-left:auto;border-color:#674253;background:#382331;color:#ffb4bf}.more{justify-self:center}
.notice,.empty,.state{padding:20px;border:1px solid #344b65;border-radius:12px;background:#172b40;color:#d4e9ff;line-height:1.6}.state{display:flex;justify-content:space-between;gap:12px}.error{color:#ffb4bf}.notice.error,.state.error{background:#382331;border-color:#674253}.presence{color:#a6b4c8;font-size:12px}
button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #8bceff;outline-offset:3px}button:disabled{cursor:not-allowed;opacity:.5}
@media(max-width:1250px){.command{grid-template-columns:repeat(3,minmax(0,1fr))}.command label:first-child{grid-column:1/-1}.list-head,.summary{gap:12px;grid-template-columns:minmax(145px,1fr) 85px minmax(145px,1fr) 150px 95px}}
@media(max-width:1000px){.list-head{display:none}.summary{grid-template-columns:minmax(0,1fr) 100px}.summary>.cell{display:none}.summary>.status{grid-column:2;grid-row:1}.facts{grid-template-columns:repeat(2,minmax(0,1fr))}.columns{grid-template-columns:1fr}}
@media(max-width:600px){.command{padding:16px;grid-template-columns:1fr}.command label:first-child{grid-column:auto}.summary{padding:16px;gap:10px}.drawer{padding:14px}.facts>span{padding:12px}.facts b{font-size:15px}.timeline article{grid-template-columns:8px minmax(0,1fr)}.timeline time{grid-column:2}.actions{display:grid;grid-template-columns:1fr 1fr}.actions label{grid-column:1/-1}.actions button{padding:8px;font-size:12px}.actions button.danger{margin-left:0}.state{flex-direction:column}}
</style>
